package kw.urtv.shared;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.net.Uri;import org.json.*;import java.util.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
/** An explicit city search, never a resident location service. */
public class LocationPickerActivity extends TvPage {
 private Place selected;private String country;private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> pending;private volatile HttpURLConnection connection;private int generation;private boolean gone;private EditText input;private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);try{selected=Place.parse(b!=null?b.getString("place"):getIntent().getStringExtra("place"));}catch(Exception e){selected=Place.load(this);}country=b==null?selected.country:b.getString("country",selected.country);if(!ContentPolicy.country(country))country=selected.country;render();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("place",selected.json());b.putString("country",country);}
 private void cancelSearch(){generation++;if(pending!=null)pending.cancel(true);HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 private void render(){title("مدينتك ومواقيت الصلاة","ابحث مرة واحدة · تُحفظ مدينتك فقط");addButton("الدولة · "+new Locale("",country).getDisplayCountry(new Locale("ar")),this::countries);
 input=new EditText(this);input.setSingleLine(true);input.setTextColor(palette.ink);input.setHintTextColor(palette.muted);input.setTextSize(20);input.setHint("اسم المدينة بالعربية أو الإنجليزية");list.addView(input);addButton("ابحث عن المدينة",this::search);
 if(country.equals("KW"))addButton("مناطق الكويت",()->{String[] a=new String[RegionCatalog.ALL.length];for(int i=0;i<a.length;i++)a[i]=RegionCatalog.ALL[i].name;new AlertDialog.Builder(this).setItems(a,(d,i)->{selected=Place.region(i);render();}).show();});
 String[][] quick={{"SA","جدة","21.4858","39.1925","Asia/Riyadh"},{"SA","مكة المكرمة","21.4225","39.8262","Asia/Riyadh"},{"SA","الرياض","24.7136","46.6753","Asia/Riyadh"},{"EG","القاهرة","30.0444","31.2357","Africa/Cairo"},{"GB","لندن","51.5085","-0.1257","Europe/London"},{"US","نيويورك","40.7143","-74.006","America/New_York"}};
 for(String[] a:quick)if(country.equals(a[0]))addButton(a[1],()->{selected=new Place(a[0],a[1],Double.parseDouble(a[2]),Double.parseDouble(a[3]),a[4],Place.methodFor(a[0]),false);render();});
 if(selected.needsConfirmation)note("تعذر تحديد الدولة من الإعداد القديم. اختر الدولة ثم المدينة لإعادة اعتماد المواقيت.");
 status=text("المحدد: "+selected.name+" · "+selected.label(),17,palette.ink);list.addView(status);
 addButton("الطريقة التلقائية حسب الدولة",()->{selected=selected.withMethod(Place.methodFor(selected.country),false);render();});
 addButton("طريقة الصلاة · "+(selected.manualMethod?"يدوية · ":"تلقائية · ")+selected.label(),()->new AlertDialog.Builder(this).setItems(Place.LABELS,(d,i)->{selected=selected.withMethod(Place.METHODS[i],true);render();}).show());
 addButton("العصر · "+(selected.hanafi?"حنفي":"شافعي / مالكي / حنبلي"),()->{selected=new Place(selected.country,selected.name,selected.lat,selected.lon,selected.zone,selected.method,!selected.hanafi,selected.manualMethod,selected.needsConfirmation);render();});
 note(selected.officialEligible()?"العجيري عند توفر الجدول؛ حساب الكويت عند تعذر تحديثه.":"مواقيت محسوبة بطريقة "+selected.label()+". قد تختلف عن جدول مسجدك؛ يمكنك تعديلها يدويًا.");
 if(Math.abs(selected.lat)>48)note("العروض العليا: سُبع الليل عند تعذر زاوية الفجر أو العشاء؛ راجع الجهة المحلية.");
 addButton("اعتماد المدينة",()->{if(selected.needsConfirmation||!country.equals(selected.country)){status.setText("اختر مدينة من الدولة المحددة أولًا");return;}setResult(RESULT_OK,new Intent().putExtra("place",selected.json()));finish();});addButton("رجوع",this::finish);note("المواقع: GeoNames عبر Open-Meteo · الحساب المحلي: Adhan");}
 private void countries(){ArrayList<String> codes=new ArrayList<>(Arrays.asList(Locale.getISOCountries()));codes.removeIf(c->!ContentPolicy.country(c));codes.sort((a,b)->new Locale("",a).getDisplayCountry(new Locale("ar")).compareTo(new Locale("",b).getDisplayCountry(new Locale("ar"))));for(String c:new String[]{"EG","SA","KW"}){codes.remove(c);codes.add(0,c);}String[] labels=new String[codes.size()];for(int i=0;i<labels.length;i++)labels[i]=new Locale("",codes.get(i)).getDisplayCountry(new Locale("ar"));new AlertDialog.Builder(this).setTitle("الدولة").setItems(labels,(d,i)->{cancelSearch();country=codes.get(i);render();}).show();}
 private void search(){String term=input.getText().toString().trim();if(term.length()<2){status.setText("اكتب حرفين على الأقل");return;}cancelSearch();final int token=generation;final String wanted=country;status.setText("جارٍ البحث…");pending=worker.submit(()->{try{if(Thread.currentThread().isInterrupted()||token!=generation)return;HttpURLConnection c=(HttpURLConnection)new URL("https://geocoding-api.open-meteo.com/v1/search?count=15&language=ar&countryCode="+wanted+"&name="+Uri.encode(term)).openConnection();connection=c;c.setConnectTimeout(7000);c.setReadTimeout(7000);JSONArray results;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[2048];int n;while((n=in.read(bytes))!=-1){out.write(bytes,0,n);if(out.size()>131072)throw new IOException();}results=new JSONObject(out.toString("UTF-8")).optJSONArray("results");}finally{c.disconnect();if(connection==c)connection=null;}
 ArrayList<Place> places=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();if(results!=null)for(int i=0;i<results.length();i++)try{JSONObject j=results.getJSONObject(i);if(!wanted.equals(j.getString("country_code")))continue;Place p=new Place(wanted,j.getString("name"),j.getDouble("latitude"),j.getDouble("longitude"),j.getString("timezone"),Place.methodFor(wanted),false);places.add(p);labels.add(p.name+" · "+(ContentPolicy.text(j.optString("admin1"))?j.optString("admin1",p.zone):p.zone));}catch(Exception ignored){}
 runOnUiThread(()->{if(gone||token!=generation)return;if(places.isEmpty()){status.setText("لم نجد المدينة. جرّب اسمها بالإنجليزية.");return;}status.setText("اختر المدينة من النتائج");new AlertDialog.Builder(this).setTitle("نتائج البحث").setItems(labels.toArray(new String[0]),(d,i)->{selected=places.get(i);render();}).show();});
 }catch(Exception e){runOnUiThread(()->{if(!gone&&token==generation)status.setText("تعذر البحث. تحقق من الإنترنت وحاول مجددًا.");});}});}
 @Override protected void onDestroy(){gone=true;cancelSearch();worker.shutdownNow();super.onDestroy();}
}
